<?php require_once __DIR__.'/../config.php';header('Content-Type: application/json; charset=utf-8');try{require_admin();$rows=db()->query("SELECT DATE(created_at) day, SUM(total) total FROM orders WHERE status<>'Cancelled' AND created_at >= DATE_SUB(CURDATE(), INTERVAL 6 DAY) GROUP BY DATE(created_at) ORDER BY day")->fetchAll();$labels=[];$values=[];for($i=6;$i>=0;$i--){$day=date('Y-m-d',strtotime("-$i days"));$labels[]=date('D',strtotime($day));$values[]=0;foreach($rows as $r){if($r['day']===$day){$values[count($values)-1]=(float)$r['total'];break;}}}echo json_encode(['labels'=>$labels,'values'=>$values]);}catch(Throwable $e){http_response_code(401);echo json_encode(['error'=>'Unauthorized or database unavailable']);}